// Auto-update (ADR 0016 M2 sub-project 3), mirrors apps/desktop's
// @tauri-apps/plugin-updater + @tauri-apps/plugin-process pairing
// (apps/desktop/src/update.ts, components/UpdatePrompt.tsx): check a
// manifest, let the user pick "update now" vs "skip this version" in the
// renderer, download + install, relaunch.
//
// electron-updater (not Electron's own built-in autoUpdater, which is
// Squirrel-based and macOS/Windows-only with a different feed shape) reads
// its feed config from app-update.yml, generated by electron-builder at
// package time from this package.json's "build.publish" block — same
// generic-HTTP-provider shape as Tauri's latest.json, just electron-builder's
// own YAML format instead of minisign. No shared manifest with apps/desktop:
// each shell ships and updates independently while both exist (through M4).
//
// Signing status (see .github/workflows/desktop-theia-build.yml):
// - Windows is code-signed when WINDOWS_CSC_LINK/WINDOWS_CSC_KEY_PASSWORD
//   CI secrets are configured. electron-updater's NsisUpdater defaults
//   verifyUpdateCodeSignature to true, which checks the downloaded
//   installer's Authenticode publisher matches the running app's — a real
//   authenticity check once those secrets exist, closer to Tauri's minisign
//   verification than the raw sha512-checksum-only story below.
// - macOS has NO Apple Developer ID / notarization yet (needs a paid Apple
//   Developer Program membership the team doesn't have), so mac.identity:
//   null still ships unsigned. Squirrel.Mac (which MacUpdater delegates to)
//   validates the downloaded bundle's code signature against the running
//   app's before install — with no identity to match, quitAndInstall() is
//   expected to error on macOS until notarization lands. Its only integrity
//   check meanwhile is the sha512 checksum electron-builder embeds in
//   latest-mac.yml, served by the same origin as the payload — a corruption
//   check, not an authenticity one; anyone who can serve or MITM that R2
//   origin could hand this app an arbitrary executable on macOS specifically.
//
// Unpackaged dev runs have no app-update.yml and no installed-app identity
// for electron-updater to reason about, so every export here is a no-op
// under !app.isPackaged — matching update.ts's isTauri() guard. Configuring
// the autoUpdater singleton (autoDownload/autoInstallOnAppQuit) is deferred
// into the isPackaged branch below rather than done at module load, since
// touching those properties constructs a platform updater (MacUpdater/
// NsisUpdater) even in dev.
const { app, ipcMain } = require('electron');
const { autoUpdater } = require('electron-updater');

const PROGRESS_CHANNEL = 'promptconnext-update-progress';

function registerUpdateLifecycle(getWindow) {
    if (!app.isPackaged) {
        // Dev/unpackaged: answer every IPC call as "no update available"
        // rather than let electron-updater throw on a missing app-update.yml.
        ipcMain.handle('promptconnext-update-check', () => null);
        ipcMain.handle('promptconnext-update-download', () => {
            throw new Error('no update to download (dev/unpackaged run)');
        });
        ipcMain.handle('promptconnext-update-install', () => {
            throw new Error('no update to install (dev/unpackaged run)');
        });
        return;
    }

    autoUpdater.autoDownload = false; // renderer decides, same as Tauri's manual downloadAndInstall
    autoUpdater.autoInstallOnAppQuit = false; // we call quitAndInstall() explicitly instead

    autoUpdater.on('download-progress', (progress) => {
        const win = getWindow();
        if (win && !win.isDestroyed()) win.webContents.send(PROGRESS_CHANNEL, progress);
    });

    ipcMain.handle('promptconnext-update-check', async () => {
        const result = await autoUpdater.checkForUpdates();
        if (!result || !result.isUpdateAvailable) return null;
        return {
            version: result.updateInfo.version,
            currentVersion: app.getVersion(),
        };
    });

    ipcMain.handle('promptconnext-update-download', async () => {
        await autoUpdater.downloadUpdate();
    });

    ipcMain.handle('promptconnext-update-install', () => {
        autoUpdater.quitAndInstall();
    });
}

module.exports = { registerUpdateLifecycle };
